def parse_json(s: str) -> object:
    """
    A simple recursive descent parser for JSON strings.
    This parser handles parsing of objects, arrays, strings, numbers, booleans, and null.
    """
    class ParseError(Exception):
        pass

    def parse_value(pos: int) -> (object, int):
        char = s[pos]

        if char == '"':
            return parse_string(pos)
        elif char.isdigit() or char == '-':
            return parse_number(pos)
        elif s.startswith('true', pos):
            return True, pos + 4
        elif s.startswith('false', pos):
            return False, pos + 5
        elif s.startswith('null', pos):
            return None, pos + 4
        elif char == '{':
            return parse_object(pos)
        elif char == '[':
            return parse_array(pos)
        else:
            raise ParseError(f"Unexpected character: {char}")

    def parse_string(start: int) -> (str, int):
        end = start + 1
        result = []
        while end < len(s):
            if s[end] == '"':
                return ''.join(result), end + 1
            elif s[end] == '\\':
                if end + 1 < len(s):
                    if s[end + 1] in ('"', '\\', '/', 'b', 'f', 'n', 'r', 't'):
                        result.append(parse_escape_sequence(s[end + 1]))
                        end += 2
                        continue
            result.append(s[end])
            end += 1
        raise ParseError("Unterminated string")

    def parse_escape_sequence(char: str) -> str:
        escape_dict = {
            '"': '"', '\\': '\\', '/': '/',
            'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
        }
        return escape_dict.get(char, char)

    def parse_number(start: int) -> (float, int):
        end = start
        if s[end] == '-':
            end += 1
        while end < len(s) and s[end].isdigit():
            end += 1
        if end < len(s) and s[end] == '.':
            end += 1
            while end < len(s) and s[end].isdigit():
                end += 1
        if end < len(s) and s[end] in ('e', 'E'):
            end += 1
            if end < len(s) and s[end] in ('+', '-'):
                end += 1
            while end < len(s) and s[end].isdigit():
                end += 1
        return float(s[start:end]), end

    def parse_object(start: int) -> (dict, int):
        obj = {}
        pos = start + 1
        while pos < len(s):
            while pos < len(s) and s[pos].isspace():
                pos += 1
            if s[pos] == '}':
                return obj, pos + 1
            key, pos = parse_string(pos)
            while pos < len(s) and s[pos].isspace():
                pos += 1
            if s[pos] != ':':
                raise ParseError("Expected ':' in object")
            pos += 1
            value, pos = parse_value(pos)
            obj[key] = value
            while pos < len(s) and s[pos].isspace():
                pos += 1
            if s[pos] == ',':
                pos += 1
                continue
            elif s[pos] == '}':
                return obj, pos + 1
            else:
                raise ParseError("Expected ',' or '}' in object")
        raise ParseError("Unterminated object")

    def parse_array(start: int) -> (list, int):
        arr = []
        pos = start + 1
        while pos < len(s):
            while pos < len(s) and s[pos].isspace():
                pos += 1
            if s[pos] == ']':
                return arr, pos + 1
            value, pos = parse_value(pos)
            arr.append(value)
            while pos < len(s) and s[pos].isspace():
                pos += 1
            if s[pos] == ',':
                pos += 1
                continue
            elif s[pos] == ']':
                return arr, pos + 1
            else:
                raise ParseError("Expected ',' or ']' in array")
        raise ParseError("Unterminated array")

    s = s.strip()
    obj, pos = parse_value(0)
    if pos != len(s):
        raise ParseError("Extra data after JSON")
    return obj

def parse_json(s: str) -> object:
    """
    A state machine approach to parse JSON strings. This method processes the input
    in a single pass by maintaining a state that tracks the context of parsing,
    allowing for efficient handling of nested structures.
    """

    class ParseError(Exception):
        pass

    index = 0

    def next_char():
        nonlocal index
        if index < len(s):
            char = s[index]
            index += 1
            return char
        return None

    def parse_number():
        start = index - 1  # includes the first character read
        while index < len(s) and (s[index].isdigit() or s[index] in ".-+eE"):
            next_char()
        return float(s[start:index])

    def parse_string():
        result = []
        while index < len(s):
            char = next_char()
            if char == '"':
                return ''.join(result)
            elif char == '\\':  # escape sequence
                escape_char = next_char()
                escape_sequences = {
                    '"': '"', '\\': '\\', '/': '/', 'b': '\b', 
                    'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }
                result.append(escape_sequences.get(escape_char, escape_char))
            else:
                result.append(char)
        raise ParseError("Unterminated string")

    def parse_array():
        arr = []
        while True:
            char = next_char()
            if char == ']':  # end of array
                return arr
            index -= 1  # backtrack to process value after '[' or comma
            if char is not None:
                arr.append(parse_value())
            if next_char() == ']':
                return arr

    def parse_object():
        obj = {}
        while True:
            char = next_char()
            if char == '}':
                return obj
            index -= 1  # backtrack
            key = parse_string()
            if next_char() != ':':
                raise ParseError("Expected ':' after key in object")
            value = parse_value()
            obj[key] = value
            if next_char() == '}':
                return obj

    def parse_value():
        char = next_char()
        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            index -= 1  # backtrack to handle number
            return parse_number()
        elif char == 't' and s[index:index + 3] == 'rue':
            index += 3
            return True
        elif char == 'f' and s[index:index + 4] == 'alse':
            index += 4
            return False
        elif char == 'n' and s[index:index + 3] == 'ull':
            index += 3
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ParseError(f"Unexpected character: {char}")

    s = s.strip()
    result = parse_value()
    if index < len(s):
        raise ParseError("Extra data after JSON")
    return result

def parse_json(s: str) -> object:
    """
    A tokenizer-based iterative parser for JSON strings. This approach first tokenizes the input
    into identifiable segments (tokens) and then processes those tokens to construct
    the corresponding Python objects.
    """

    class ParseError(Exception):
        pass

    tokens = []
    index = 0
    length = len(s)

    def tokenize():
        nonlocal index
        while index < length:
            if s[index].isspace():
                index += 1
                continue
            elif s[index] == '{':
                tokens.append('{')
                index += 1
            elif s[index] == '}':
                tokens.append('}')
                index += 1
            elif s[index] == '[':
                tokens.append('[')
                index += 1
            elif s[index] == ']':
                tokens.append(']')
                index += 1
            elif s[index] == ':':
                tokens.append(':')
                index += 1
            elif s[index] == ',':
                tokens.append(',')
                index += 1
            elif s[index] == '"':
                start = index + 1
                index += 1
                while index < length and s[index] != '"':
                    if s[index] == '\\':
                        index += 1
                    index += 1
                if index >= length:
                    raise ParseError("Unterminated string")
                tokens.append(s[start:index])
                index += 1
            elif s[index].isdigit() or s[index] == '-' or s[index] == '+':
                start = index
                index += 1
                while index < length and (s[index].isdigit() or s[index] in 'eE-+'):
                    index += 1
                tokens.append(float(s[start:index]))
            elif s.startswith('true', index):
                tokens.append(True)
                index += 4
            elif s.startswith('false', index):
                tokens.append(False)
                index += 5
            elif s.startswith('null', index):
                tokens.append(None)
                index += 4
            else:
                raise ParseError(f"Unexpected character: {s[index]}")

    def parse_value():
        token = tokens.pop(0)
        if token == '{':
            return parse_object()
        elif token == '[':
            return parse_array()
        elif isinstance(token, str):
            return token
        else:
            return token

    def parse_object():
        obj = {}
        while tokens and tokens[0] != '}':
            key = tokens.pop(0)
            if tokens.pop(0) != ':':
                raise ParseError("Expected ':' after key in object")
            value = parse_value()
            obj[key] = value
            if tokens and tokens[0] == ',':
                tokens.pop(0)
        if not tokens or tokens.pop(0) != '}':
            raise ParseError("Expected '}' to close object")
        return obj

    def parse_array():
        arr = []
        while tokens and tokens[0] != ']':
            arr.append(parse_value())
            if tokens and tokens[0] == ',':
                tokens.pop(0)
        if not tokens or tokens.pop(0) != ']':
            raise ParseError("Expected ']' to close array")
        return arr

    tokenize()
    parsed_value = parse_value()
    if tokens:
        raise ParseError("Extra data after JSON")
    return parsed_value

