    An iterative approach using a stack to parse JSON strings. This strategy processes the input character by character,
    pushing and popping from the stack to build nested structures, thereby avoiding recursion.
    """

    class ParseError(Exception):
        pass

    stack = []
    i = 0
    n = len(s)

    def next_char():
        nonlocal i
        if i >= n:
            return None
        char = s[i]
        i += 1
        return char

    def parse_string():
        result = []
        char = next_char()
        while char is not None:
            if char == '"':
                return ''.join(result)
            elif char == '\\':
