                    '"': '"', '\\': '\\', '/': '/', 
                    'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }
                result.append(escape_sequences.get(escape_char, escape_char))
            else:
                result.append(char)
            char = next_char()
