    def parse_number(start):
        end = start
        while end < n and (s[end].isdigit() or s[end] in '.-eE'):
            end += 1
        return float(s[start:end]), end

    while i < n:
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break
        char = s[i]

        if char == '{':
            stack.append({})
            i += 1
        elif char == '}':
            if len(stack) == 0 or not isinstance(stack[-1], dict):
                raise ParseError("Unexpected '}'")
            obj = stack.pop()
            if stack:
                if isinstance(stack[-1], list):
                    stack[-1].append(obj)
                elif isinstance(stack[-1], dict):
