            else:
                return string_value
            continue
        elif char.isdigit() or char == '-':
            number_value, next_pos = parse_number(i)
            if stack:
                if isinstance(stack[-1], list):
                    stack[-1].append(number_value)
                elif isinstance(stack[-1], dict):
                    stack[-1][None] = number_value  # placeholder for key
            else:
